// ── TILLU Input Normalizer ──────────────────────────────────────
// Normalize incoming message from any client (WhatsApp, Web, Mobile)
const msg = $input.first().json;
const now = new Date();

// Detect script: Devanagari = Hindi
const hindiPattern = /[\u0900-\u097F]/;
const detectedLang = hindiPattern.test(msg.text || '') ? 'hi' : 'en';

// Time-of-day context
const hour = now.getHours();
let period = 'day';
if (hour >= 5 && hour < 12) period = 'morning';
else if (hour >= 12 && hour < 17) period = 'afternoon';
else if (hour >= 17 && hour < 21) period = 'evening';
else period = 'night';

return {
  json: {
    user_id: msg.user_id || 'default',
    text: (msg.text || '').trim(),
    media_url: msg.media_url || null,
    session_id: msg.session_id || `sess_${Date.now()}`,
    client_id: msg.client_id || 'web',
    detected_lang: detectedLang,
    time_period: period,
    timestamp: now.toISOString(),
    raw: msg
  }
};

// ── TILLU Brain Router ──────────────────────────────────────────
// Merge all parallel results and decide which chain to invoke
const all = $input.all();

// Find each result by node name (order may vary)
const find = (name) => all.find(i => i.pairedItem?.node === name)?.json || {};

const base = all[0].json;  // normalized input (passed through)
const recentMem = find('Fetch Recent Memory');
const semanticMem = find('Semantic Memory Search');
const intent = find('Classify Intent');
const emotion = find('Detect Emotion + Stress');

const intentClass = intent.intent_class || 'small_talk';
const stressLevel = emotion.stress_level || 'low';
const dominantEmotion = emotion.dominant_emotion || 'neutral';
const lang = base.detected_lang || 'en';

// ── Chain selection logic ────────────────────────────────────────
let chain = 'conversational';
let priority = 'normal';

if (stressLevel === 'high' || intentClass === 'distress' || dominantEmotion === 'sadness') {
  chain = 'empathy';
  priority = 'urgent';
} else if (intentClass === 'research_request' || intentClass === 'deep_analysis') {
  chain = 'research';
} else if (intentClass === 'action_required' || intentClass === 'multi_step_task') {
  chain = 'react_agent';
} else if (intentClass === 'pattern_query' || intentClass === 'data_analysis') {
  chain = 'analysis';
} else if (intentClass === 'memory_query') {
  chain = 'memory_recall';
} else if (intentClass === 'web_search') {
  chain = 'research';  // research chain uses web search tool
}

// ── Memory context assembly ──────────────────────────────────────
const memoryContext = {
  recent_turns: recentMem.interactions || [],
  semantic_matches: semanticMem.results || [],
  turn_count: (recentMem.interactions || []).length
};

return {
  json: {
    // Original input
    user_id: base.user_id,
    text: base.text,
    session_id: base.session_id,
    client_id: base.client_id,
    timestamp: base.timestamp,
    // Language
    lang: lang,
    time_period: base.time_period,
    // Intelligence
    intent_class: intentClass,
    emotion_scores: emotion.scores || {},
    dominant_emotion: dominantEmotion,
    stress_level: stressLevel,
    // Routing
    target_chain: chain,
    priority: priority,
    // Memory
    memory_context: memoryContext
  }
};

// ── Personality Compiler ────────────────────────────────────────
// Apply TILLU's personality based on context
const response = $input.first().json;
const chain_input = $node['TILLU Brain Router'].json;

const stress = chain_input.stress_level;
const period = chain_input.time_period;
const lang = chain_input.lang;
const emotion = chain_input.dominant_emotion;

// Personality mode selection
let mode = 'sharp';
if (stress === 'high' || emotion === 'sadness') mode = 'empathic';
else if (period === 'morning') mode = 'energetic';
else if (period === 'evening' || period === 'night') mode = 'warm';
else if (emotion === 'joy') mode = 'playful';

// Language-aware response prefix (subtle, not forced)
const langNote = lang === 'hi' ? 'hindi_primary' : 'english_primary';

return {
  json: {
    // Response
    response_text: response.content || response.response || '',
    chain_used: chain_input.target_chain,
    // Metadata
    personality_mode: mode,
    lang: lang,
    lang_mode: langNote,
    session_id: chain_input.session_id,
    user_id: chain_input.user_id,
    intent_class: chain_input.intent_class,
    // For storage
    interaction_data: {
      user_id: chain_input.user_id,
      session_id: chain_input.session_id,
      user_message: chain_input.text,
      tillu_response: response.content || response.response || '',
      chain: chain_input.target_chain,
      intent: chain_input.intent_class,
      emotion: chain_input.dominant_emotion,
      stress: chain_input.stress_level,
      lang: lang,
      quality_score: response.quality_score || null,
      timestamp: chain_input.timestamp
    }
  }
};
